package com.example.lending.application.port.in;

import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

public interface ListActiveLoansUseCase {

    ActiveLoanPage listActiveLoans(ListActiveLoansQuery query);

    record ListActiveLoansQuery(UUID memberId, int page, int size) {

        public ListActiveLoansQuery {
            if (memberId == null) {
                throw new IllegalArgumentException("memberId is required");
